static char *read_all(void) {
    size_t cap = 1 << 16, len = 0;
    char *buf = malloc(cap);
    for (;;) {
        if (len + 1 >= cap) buf = realloc(buf, cap *= 2);
        size_t r = fread(buf + len, 1, cap - len - 1, stdin);
        if (r == 0) break;
        len += r;
    }
    buf[len] = '\0';
    return buf;
}

int main(void) {
    char *input = read_all();
    char *line2 = strchr(input, '\n');
    if (line2) *line2++ = '\0'; else line2 = "";
    int cap = 16, n = 0;
    long long *nums = malloc(cap * sizeof *nums);
    char *p = input, *end;
    for (;;) {
        long long v = strtoll(p, &end, 10);
        if (end == p) break;
        if (n == cap) nums = realloc(nums, (cap *= 2) * sizeof *nums);
        nums[n++] = v;
        p = end;
    }
    long long target = strtoll(line2, NULL, 10);
    int out[2];
