package main

import (
	"bufio"
	"fmt"
	"os"
	"sort"
	"strconv"
	"strings"
)

func solve(nums []int64, target int64) []int {
	// Return the indices [i, j] (i < j) of the two numbers that add up to target.
	return []int{}
}

func main() {
	reader := bufio.NewReader(os.Stdin)
	line, _ := reader.ReadString('\n')
	fields := strings.Fields(line)
	nums := make([]int64, len(fields))
	for i, f := range fields {
		nums[i], _ = strconv.ParseInt(f, 10, 64)
	}
	line, _ = reader.ReadString('\n')
	target, _ := strconv.ParseInt(strings.TrimSpace(line), 10, 64)
	ans := solve(nums, target)
	sort.Ints(ans)
	out := make([]string, len(ans))
	for i, v := range ans {
		out[i] = strconv.Itoa(v)
	}
	fmt.Println(strings.Join(out, " "))
}

